# Any graph with an on_message method is an actor
graph Counter {
    count: 0

    fn on_message(msg) {
        if msg == "increment" {
            count = count + 1
        }
        if msg == "get" {
            return count
        }
    }
}

# spawn with a graph creates an actor
counter = spawn Counter{}
counter.send("increment")
counter.send("increment")
result = counter.request("get")
print(result)  # 2
counter.close()

