# signal.on(sym) returns a channel that receives when the signal fires
sigint_ch = signal.on(:sigint)

# Combine with a timeout for a graceful shutdown pattern
timeout = timer.after(5000)

result = select(sigint_ch, timeout)
if result[0] == sigint_ch {
    print("Received SIGINT, shutting down...")
} else {
    print("Timeout, continuing...")
}

sigint_ch.close()

# Inherit from the built-in supervisor template
graph MySupervisor from supervisor {
    fn on_message(msg) {
        return "supervisor got: " + msg
    }
}

graph Worker {
    fn on_message(msg) {
        return "working on: " + msg
    }
}

sup = spawn MySupervisor{}
worker = spawn Worker{}

# Register the worker for supervision
sup.supervise(worker)

# The worker will be automatically restarted if it crashes
result = worker.request("task")
print(result)  # "working on: task"

sup.close()

