graph Worker {
    id: 0
    fn on_message(msg) {
        return "worker " + id.to_string() + " processed: " + msg
    }
}

# Create a pool of workers
workers = []
i = 0
while i < 3 {
    workers.append!(spawn Worker{ id: i })
    i = i + 1
}

# Round-robin dispatch
tasks = ["task_a", "task_b", "task_c", "task_d", "task_e"]
for task in tasks {
    idx = tasks.index_of(task) % workers.length()
    result = workers[idx].request(task)
    print(result)
}

# Clean up
for w in workers {
    w.close()
}

